import torch,sys,json,hashlib,time
started=time.process_time()
a,b=[torch.load(p,map_location='cpu',weights_only=True) for p in sys.argv[1:]]
if set(a)!=set(b):raise ValueError('schema mismatch')
for key in a:
 if key in ('actor','critic'):
  if list(a[key])!=list(b[key]):raise ValueError('parameter keys')
  for name in a[key]:
   left,right=a[key][name],b[key][name]
   if left.dtype!=right.dtype or left.shape!=right.shape or not torch.equal(left,right):raise ValueError('tensor mismatch '+key+'/'+name)
 elif a[key]!=b[key]:raise ValueError('scalar mismatch '+key)
print(json.dumps({'status':'PASS','both_runtime_files_loaded':sys.argv[1:],'all_tensors_and_scalars_equal':True,'actor_sha256':a['actor_sha256'],'critic_sha256':a['critic_sha256'],'cpu_seconds':time.process_time()-started,'optimizer_steps':0}))
